.adventure-map {
  position: relative;
  width: 100%;
  max-width: 100%;
  /* สัดส่วนจริงของภาพพื้นหลัง (1139x1437) กัน object-fit: cover ครอบตัดบน/ล่าง
     ทิ้งจนตำแหน่ง % ของติ๊กถูกคลาดเคลื่อนจากภาพจริง */
  aspect-ratio: 1139 / 1437;
  box-sizing: border-box;
  border-radius: 1.25rem;
  overflow: hidden;
  border: 3px solid var(--farm-wood);
  box-shadow: 0 14px 30px -14px rgba(74, 47, 24, 0.5);
  background: var(--farm-cream-dark);
}

.adventure-map__bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  user-select: none;
  pointer-events: none;
}

/* จุดยึดตำแหน่ง — ตัวเปล่านี้ไม่แสดงอะไรเลยถ้ายังไม่ผ่านฐาน (หมุด/ตึก/ป้ายชื่อ
   ทั้งหมดอยู่ในภาพพื้นหลังแล้ว) จะเห็นแค่ติ๊กถูกโผล่มาตอนผ่านฐานแล้วเท่านั้น */
.station-check-slot {
  position: absolute;
  transform: translate(-50%, -100%);
  z-index: 10;
  pointer-events: none;
}

.station-check {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 1.5rem;
  height: 1.5rem;
  border-radius: 50%;
  background: #5fb648;
  border: 2.5px solid #fff8ec;
  box-shadow: 0 3px 6px rgba(74, 47, 24, 0.5);
}

.station-check__icon {
  width: 0.9rem;
  height: 0.9rem;
  color: #fff;
}

/* [ใหม่] จุดเริ่มต้น — หมุดคงที่ + ป้ายชื่อเล็ก ๆ ใต้หมุด แสดงตลอดเวลา */
.start-point {
  position: absolute;
  transform: translate(-50%, -100%);
  z-index: 10;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.2rem;
  pointer-events: none;
}

.start-point__badge {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 1.6rem;
  height: 1.6rem;
  border-radius: 50%;
  background: var(--farm-accent-dark);
  border: 2.5px solid #fff8ec;
  box-shadow: 0 3px 6px rgba(74, 47, 24, 0.5);
}

.start-point__icon {
  width: 1rem;
  height: 1rem;
  color: #fff;
}

.start-point__label {
  padding: 0.1rem 0.45rem;
  border-radius: 0.4rem;
  background: rgba(74, 47, 24, 0.75);
  color: #fff8ec;
  font-size: 0.6rem;
  font-weight: 700;
  white-space: nowrap;
}
